1	// Package log implements an append-only, batch-commit segmented log.
2	//
3	// A writer stages a batch of opaque records with Append and publishes it
4	// atomically with Commit. Readers only ever see committed batches, in
5	// strictly increasing sequence order starting at 1.
6	package log
7	
8	import (
9		"errors"
10		"fmt"
11		"os"
12		"path/filepath"
13		"sort"
14		"strconv"
15		"strings"
16		"sync"
17	)
18	
19	var (
20		// ErrNotCommitted is returned when reading a sequence that has been
21		// staged with Append but not yet committed.
22		ErrNotCommitted = errors.New("log: batch not committed")
23		// ErrUnknownBatch is returned for sequence 0, sequences that were
24		// never reserved, sequences beyond the reserved range, and batches
25		// that have already been committed.
26		ErrUnknownBatch = errors.New("log: unknown batch")
27		// ErrCorruptSegment is returned when a segment file fails validation
28		// while opening or scanning the log.
29		ErrCorruptSegment = errors.New("log: corrupt segment")
30		// ErrInvalidOptions is returned by Open when the options are not
31		// usable, e.g. a non-positive segment capacity.
32		ErrInvalidOptions = errors.New("log: invalid options")
33	)
34	
35	var errClosed = errors.New("log: closed")
36	
37	// Options configures a Log opened with Open.
38	type Options struct {
39		// SegmentBytes is the capacity of one segment file in bytes. Once a
40		// non-empty segment would exceed it, the log rolls to a new segment.
41		// A single batch larger than the capacity occupies its own segment.
42		// Must be positive.
43		SegmentBytes int
44		// Sync makes Commit fsync the segment file before returning, so a
45		// returned commit is durable.
46		Sync bool
47	}
48	
49	// Batch is a group of records identified by a single sequence number.
50	// A Batch returned by Append is staged; after Commit it is readable.
51	type Batch struct {
52		seq     uint64
53		records [][]byte
54		owner   *Log
55	}
56	
57	// Seq returns the sequence number reserved for the batch.
58	func (b Batch) Seq() uint64 { return b.seq }
59	
60	// Records returns a copy of the batch's records.
61	func (b Batch) Records() [][]byte { return copyRecords(b.records) }
62	
63	// Segment describes one segment file by the committed sequences it holds.
64	type Segment struct {
65		FirstSeq uint64
66		LastSeq  uint64
67	}
68	
69	// Log is an append-only batch-commit log stored in a directory of
70	// segment files. It is safe for concurrent use, but the writer side is
71	// expected to be a single goroutine (see README Limits).
72	type Log struct {
73		dir  string
74		opts Options
75	
76		mu         sync.Mutex
77		file       *os.File // current segment, nil until first write
78		fileSize   int
79		segIndex   int // index of the current segment file, 0 = none yet
80		curBatches int // committed batches in the current segment
81		nextSeq    uint64
82		staged     map[uint64][][]byte
83		committed  map[uint64][][]byte
84		segs       []Segment // segments holding at least one committed batch
85		closed     bool
86	}
87	
88	// Open opens the log in dir, creating the directory if needed. Existing
89	// segments are validated and their committed batches become readable.
90	func Open(dir string, opts Options) (*Log, error) {
91		if opts.SegmentBytes <= 0 {
92			return nil, ErrInvalidOptions
93		}
94		if err := os.MkdirAll(dir, 0o755); err != nil {
95			return nil, err
96		}
97		entries, err := os.ReadDir(dir)
98		if err != nil {
99			return nil, err
100		}
101		var indices []int
102		for _, e := range entries {
103			if e.IsDir() || !strings.HasSuffix(e.Name(), ".seg") {
104				continue
105			}
106			n, err := strconv.Atoi(strings.TrimSuffix(e.Name(), ".seg"))
107			if err != nil {
108				continue
109			}
110			indices = append(indices, n)
111		}
112		sort.Ints(indices)
113	
114		l := &Log{
115			dir:       dir,
116			opts:      opts,
117			nextSeq:   1,
118			staged:    make(map[uint64][][]byte),
119			committed: make(map[uint64][][]byte),
120		}
121		for _, n := range indices {
122			data, err := os.ReadFile(l.segmentPath(n))
123			if err != nil {
124				return nil, err
125			}
126			batches, err := parseSegment(data)
127			if err != nil {
128				return nil, err
129			}
130			if len(batches) == 0 {
131				continue // empty segment, e.g. created just before a crash
132			}
133			seg := Segment{FirstSeq: ^uint64(0)}
134			for _, pb := range batches {
135				l.committed[pb.seq] = pb.records
136				if pb.seq < seg.FirstSeq {
137					seg.FirstSeq = pb.seq
138				}
139				if pb.seq > seg.LastSeq {
140					seg.LastSeq = pb.seq
141				}
142			}
143			l.segs = append(l.segs, seg)
144			if seg.LastSeq >= l.nextSeq {
145				l.nextSeq = seg.LastSeq + 1
146			}
147		}
148		if len(indices) > 0 {
149			l.segIndex = indices[len(indices)-1]
150			if err := l.openCurrent(); err != nil {
151				return nil, err
152			}
153		}
154		return l, nil
155	}
156	
157	// Append stages a batch of records and reserves the next sequence number
158	// for it. The batch becomes readable only after Commit.
159	func (l *Log) Append(records [][]byte) (Batch, error) {
160		l.mu.Lock()
161		defer l.mu.Unlock()
162		if l.closed {
163			return Batch{}, errClosed
164		}
165		recs := copyRecords(records)
166		seq := l.nextSeq
167		l.nextSeq++
168		l.staged[seq] = recs
169		return Batch{seq: seq, records: recs, owner: l}, nil
170	}
171	
172	// Commit makes a staged batch durable and readable, and returns its
173	// reserved sequence number. Committing a batch that is not staged —
174	// including one already committed — returns ErrUnknownBatch.
175	func (l *Log) Commit(b Batch) (uint64, error) {
176		l.mu.Lock()
177		defer l.mu.Unlock()
178		if l.closed {
179			return 0, errClosed
180		}
181		recs, ok := l.staged[b.seq]
182		if !ok || b.owner != l {
183			return 0, ErrUnknownBatch
184		}
185		entry := encodeBatch(b.seq, recs)
186		if err := l.writeEntry(entry); err != nil {
187			return 0, err
188		}
189		var syncErr error
190		if l.opts.Sync {
191			syncErr = l.file.Sync()
192		}
193		delete(l.staged, b.seq)
194		l.committed[b.seq] = recs
195		if l.curBatches == 0 {
196			l.segs = append(l.segs, Segment{FirstSeq: b.seq, LastSeq: b.seq})
197		} else {
198			seg := &l.segs[len(l.segs)-1]
199			if b.seq < seg.FirstSeq {
200				seg.FirstSeq = b.seq
201			}
202			if b.seq > seg.LastSeq {
203				seg.LastSeq = b.seq
204			}
205		}
206		l.curBatches++
207		return b.seq, syncErr
208	}
209	
210	// Read returns the records of the committed batch with the given
211	// sequence. A staged but uncommitted sequence yields ErrNotCommitted;
212	// sequence 0, never-reserved sequences, and sequences beyond the
213	// reserved range yield ErrUnknownBatch.
214	func (l *Log) Read(seq uint64) ([][]byte, error) {
215		l.mu.Lock()
216		defer l.mu.Unlock()
217		if l.closed {
218			return nil, errClosed
219		}
220		if recs, ok := l.committed[seq]; ok {
221			return copyRecords(recs), nil
222		}
223		if _, ok := l.staged[seq]; ok {
224			return nil, ErrNotCommitted
225		}
226		return nil, ErrUnknownBatch
227	}
228	
229	// Scan replays committed batches with sequence >= from in increasing
230	// sequence order, stopping at the first error returned by fn.
231	func (l *Log) Scan(from uint64, fn func(Batch) error) error {
232		l.mu.Lock()
233		if l.closed {
234			l.mu.Unlock()
235			return errClosed
236		}
237		seqs := make([]uint64, 0, len(l.committed))
238		for seq := range l.committed {
239			if seq >= from {
240				seqs = append(seqs, seq)
241			}
242		}
243		sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
244		batches := make([]Batch, len(seqs))
245		for i, seq := range seqs {
246			batches[i] = Batch{seq: seq, records: l.committed[seq], owner: l}
247		}
248		l.mu.Unlock()
249		for _, b := range batches {
250			if err := fn(b); err != nil {
251				return err
252			}
253		}
254		return nil
255	}
256	
257	// Segments lists the segments that hold committed batches, in file
258	// order, each with its first and last committed sequence.
259	func (l *Log) Segments() []Segment {
260		l.mu.Lock()
261		defer l.mu.Unlock()
262		out := make([]Segment, len(l.segs))
263		copy(out, l.segs)
264		return out
265	}
266	
267	// Close closes the current segment file. The log must not be used
268	// afterwards.
269	func (l *Log) Close() error {
270		l.mu.Lock()
271		defer l.mu.Unlock()
272		if l.closed {
273			return nil
274		}
275		l.closed = true
276		if l.file != nil {
277			return l.file.Close()
278		}
279		return nil
280	}
281	
282	// writeEntry appends one encoded batch to the current segment, rolling
283	// to a new segment when the current one is non-empty and would exceed
284	// the configured capacity.
285	func (l *Log) writeEntry(entry []byte) error {
286		if l.file != nil && l.fileSize > 0 && l.fileSize+len(entry) > l.opts.SegmentBytes {
287			if err := l.file.Close(); err != nil {
288				return err
289			}
290			l.file = nil
291			l.segIndex++
292			l.curBatches = 0
293		}
294		if l.file == nil {
295			if l.segIndex == 0 {
296				l.segIndex = 1
297			}
298			if err := l.openCurrent(); err != nil {
299				return err
300			}
301		}
302		n, err := l.file.Write(entry)
303		if err != nil {
304			return err
305		}
306		l.fileSize += n
307		return nil
308	}
309	
310	func (l *Log) openCurrent() error {
311		f, err := os.OpenFile(l.segmentPath(l.segIndex), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
312		if err != nil {
313			return err
314		}
315		st, err := f.Stat()
316		if err != nil {
317			f.Close()
318			return err
319		}
320		l.file = f
321		l.fileSize = int(st.Size())
322		return nil
323	}
324	
325	func (l *Log) segmentPath(index int) string {
326		return filepath.Join(l.dir, fmt.Sprintf("%06d.seg", index))
327	}
328	
329	func copyRecords(records [][]byte) [][]byte {
330		out := make([][]byte, len(records))
331		for i, r := range records {
332			cp := make([]byte, len(r))
333			copy(cp, r)
334			out[i] = cp
335		}
336		return out
337	}
