				seg.FirstSeq = pb.seq
			}
			if pb.seq > seg.LastSeq {
				seg.LastSeq = pb.seq
			}
		}
		l.segs = append(l.segs, seg)
		if seg.LastSeq >= l.nextSeq {
			l.nextSeq = seg.LastSeq + 1
		}
		if last {
			l.curBatches = len(batches)
		}
	}
	if len(indices) > 0 {
		l.segIndex = indices[len(indices)-1]
		if err := l.openCurrent(); err != nil {
